class IdentifyCommitteeModule(dspy.Module):
    def __init__(self):
        super().__init__()
        # LLM is a LAST RESORT only: used when deterministic extraction of the
        # FEC "Paid for by ..." disclaimer fails or is not confident.
        self.fallback = dspy.Predict(dspy.Signature(
            'email_body: str -> committee: str',
            "You are given the raw text of a political fundraising email. Identify the political "
            "committee that sponsored (paid for) the email.\n\n"
            "Domain knowledge: U.S. political fundraising emails are legally required to carry a "
            "disclaimer naming the paying committee, usually near the very bottom, worded like "
            "'Paid for by <COMMITTEE NAME>' or 'Paid for and authorized by <COMMITTEE NAME>', often "
            "followed by 'and not authorized by any candidate or candidate's committee', a mailing "
            "address, a website, and unsubscribe text. The committee name is also frequently "
            "repeated immediately afterwards in the footer sender/address block (so the same name can "
            "appear twice back-to-back, sometimes with no space between the copies), or in the "
            "sending domain, or in a line like 'Contributions or gifts to <NAME> are not tax "
            "deductible' or 'to stop receiving emails from <NAME>'.\n\n"
            "Rules:\n"
            "- Return the committee's name exactly as printed in the disclaimer, in normal mixed-case "
            "form (if the disclaimer is ALL CAPS but the same name appears elsewhere in mixed case, "
            "use the mixed-case spelling).\n"
            "- If the name appears twice in a row, return it only ONCE.\n"
            "- Committee names may legitimately contain small numerals or digits-as-words (e.g. a "
            "number standing for a district, a state, or an election year). Keep those digits; they "
            "are part of the name. Do NOT keep street numbers, PO Box numbers, ZIP codes, or phone "
            "numbers.\n"
            "- Drop a grammatical article that merely introduces the name: 'Paid for by the <NAME>' "
            "means the committee is '<NAME>', without 'the'. Only keep a leading 'The' when it is "
            "clearly part of the registered name (capitalized and used that way elsewhere).\n"
            "- If the disclaimer names the committee by its acronym/initialism, return that acronym in "
            "capital letters exactly as printed; do NOT expand it into the long form, and do not "
            "invent a long form.\n"
            "- Keep words like Fund, Committee, PAC, Party, Victory, Action, 'for Congress', "
            "'for Senate' that are part of the name.\n"
            "- Exclude street address, PO Box, city/state/ZIP, phone numbers, URLs, 'not authorized by "
            "any candidate...' language, 'a joint fundraising committee composed of...' explanations, "
            "and any trailing punctuation.\n"
            "- Do NOT return a candidate's bare personal name unless that literally is the committee "
            "name; do not abbreviate or reword a name that is not in the text.\n"
            "- The email text may have words glued together by line wrapping; restore normal spacing.\n"
            "- Output only the committee name, nothing else."
        ))

    def forward(self, **inputs):
        import re

        body = inputs.get("email_body") or ""

        def normalize_ws(t: str) -> str:
            """Strip invisible/padding characters and collapse all whitespace to single spaces."""
            for ch in ("\u034f", "\u00ad", "\u200b", "\u200c", "\u200d", "\u2060", "\ufeff", "\xa0"):
                t = t.replace(ch, " ")
            t = t.replace("\u2019", "'").replace("\u2018", "'")
            return re.sub(r"\s+", " ", t).strip()

        text = normalize_ws(body)

        def flex(phrase: str) -> str:
            """Regex for a phrase tolerating missing/extra whitespace between its words."""
            return r"\s*".join(re.escape(w) for w in phrase.split())

        # Openers that introduce the paying committee, longest/most specific first.
        opener_re = re.compile(
            "|".join([
                flex("paid for and authorized by"),
                flex("authorized and paid for by"),
                flex("paid for by authority of"),
                flex("paid for by"),
                flex("sponsored by"),
            ]) + r"\s*:?\s*",
            re.I,
        )

        # Phrases that must terminate the committee name.
        stop_phrases = [
            "not authorized", "and not authorized", "authorized by any",
            "not paid for at taxpayer", "all rights reserved", "unsubscribe",
            "po box", "p.o. box", "post office box", "united states",
            "contributions to", "contributions from", "contributions are",
            "contributions or gifts", "gifts to", "not tax deductible",
            "federal law", "privacy policy", "click here", "if you",
            "this email", "this message", "sent via", "view this email",
            "update your", "copyright", "text ",
            "paid for by", "www.", "http",
            "not affiliated", "a joint fundraising", "joint fundraising committee",
            "is a grassroots", "suite ", "ste ", "attn",
        ]
        stop_re = re.compile("|".join(flex(p) if " " in p.strip() else re.escape(p.strip())
                                     for p in stop_phrases), re.I)

        # Number patterns that indicate the address block has started. NOTE: short numerals
        # (1-2 digits) and 4-digit years can be part of a committee name (district numbers,
        # state numbers, election years), so they must NOT terminate the name.
        addr_num_re = re.compile(r"\s(?!19\d\d(?!\d))(?!20\d\d(?!\d))\d{3,}")
        ordinal_re = re.compile(r"\s\d{1,2}(?:st|nd|rd|th)\b", re.I)

        def cut_segment(seg: str) -> str:
            """Truncate the text following a disclaimer opener at the end of the committee name."""
            limits = [len(seg)]
            for rx in (stop_re, addr_num_re, ordinal_re):
                m = rx.search(seg)
                if m and m.start() > 0:
                    limits.append(m.start())
            for pat in (r"\.(?=\s|$)", r"[,;:!?|\u2022\u00a9()\[\]]", r"\s[\u2014\u2013-]\s"):
                m = re.search(pat, seg)
                if m and m.start() > 0:
                    limits.append(m.start())
            return seg[:min(limits)]

        def strip_edges(s: str) -> str:
            """Remove surrounding punctuation and dangling connective words."""
            s = s.strip(" \t.,;:!?-\u2013\u2014&|*\"'()[]")
            for _ in range(4):
                words = s.split()
                if words and words[-1].lower() in ("and", "or", "&", "not", "of", "for", "by", "the"):
                    s = " ".join(words[:-1]).strip(" .,;:-&|")
                else:
                    break
            return s.strip()

        def strip_article(s: str, hay: str) -> str:
            """Drop a leading article that merely introduces the committee name.

            'Paid for by the NRCC' names the committee 'NRCC', not 'the NRCC'. A lowercase
            'the'/'a'/'an' is always an article. A capitalized 'The' is dropped only when the
            same name also appears elsewhere preceded by a lowercase 'the' (proving it is an
            article rather than part of the registered name).
            """
            for _ in range(2):
                words = s.split()
                if len(words) < 2 or words[0].lower() not in ("the", "a", "an"):
                    break
                rest = " ".join(words[1:])
                if words[0].islower():
                    s = rest
                    continue
                try:
                    if re.search(r"(?<![A-Za-z])(the|a|an)\s+" + re.escape(rest), hay):
                        s = rest
                        continue
                except re.error:
                    pass
                break
            return s.strip()

        def compact(s: str) -> str:
            return re.sub(r"[^a-z0-9]", "", s.lower())

        compact_text = compact(text)

        def score(s: str) -> int:
            """Prefer mixed-case, properly-spaced renderings of the same name."""
            has_lower = any(c.islower() for c in s)
            has_upper = any(c.isupper() for c in s)
            base = 10 if (has_lower and has_upper) else (5 if has_lower else 0)
            return base + len(s.split())

        def char_dedup(s: str) -> str:
            """Collapse a name printed twice back-to-back, even when the copies are glued
            together with no space (e.g. disclaimer immediately followed by the footer
            sender block). Compares the alphanumeric characters only, case-insensitively,
            and keeps the better-spelled copy."""
            marks = [(i, c) for i, c in enumerate(s) if c.isalnum()]
            n = len(marks)
            if n < 6 or n % 2 != 0:
                return s
            half = n // 2
            first = "".join(c for _, c in marks[:half]).lower()
            second = "".join(c for _, c in marks[half:]).lower()
            if first != second:
                return s
            cut = marks[half][0]
            a = strip_edges(s[:cut])
            b = strip_edges(s[cut:])
            if not a:
                return b
            if not b:
                return a
            return a if score(a) >= score(b) else b

        def word_dedup(words: list) -> list:
            """Collapse a name that was printed twice back-to-back on word boundaries."""
            for _ in range(3):
                changed = False
                n = len(words)
                for k in range(1, n):
                    a, b = words[:k], words[k:]
                    ca, cb = compact(" ".join(a)), compact(" ".join(b))
                    if ca and ca == cb:
                        words = b if len(b) >= len(a) else a
                        changed = True
                        break
                if not changed:
                    break
            return words

        def is_acronym(s: str) -> bool:
            """True for a single all-capitals initialism such as a committee's short name."""
            toks = s.split()
            return (len(toks) == 1 and s.isalpha() and s.isupper() and 2 <= len(s) <= 6)

        def best_variant(cand: str, hay: str) -> str:
            """Find the best-spelled/cased occurrence of the same letters elsewhere in the email."""
            chars = [c for c in cand if not c.isspace()]
            if not chars or len(chars) > 70:
                return cand
            pat = r"\s*".join(re.escape(c) for c in chars)
            best, best_score = cand, score(cand)
            cand_tokens = len(cand.split())
            try:
                for m in re.finditer(pat, hay, re.I):
                    # Reject matches embedded inside a longer word.
                    before = hay[m.start() - 1] if m.start() > 0 else " "
                    after = hay[m.end()] if m.end() < len(hay) else " "
                    if before.isalnum() or after.isalnum():
                        continue
                    s = re.sub(r"\s+", " ", m.group(0)).strip()
                    if len(s.split()) > cand_tokens + 2:
                        continue
                    sc = score(s)
                    if sc > best_score:
                        best, best_score = s, sc
            except re.error:
                return cand
            return best

        def title_case(s: str) -> str:
            """Convert an ALL-CAPS committee name to conventional capitalization."""
            small = {"for", "of", "and", "the", "a", "an", "to", "in", "on", "at", "by", "or"}
            acronyms = {"pac", "gop", "dccc", "dscc", "nrsc", "nrcc", "rnc", "dnc",
                        "us", "usa", "scf", "nra", "pa", "oh", "tx", "ii", "iii"}
            vowels = set("aeiouy")
            out = []
            for i, w in enumerate(s.split()):
                wl = w.lower()
                core = re.sub(r"[^a-z0-9]", "", wl)
                if i > 0 and wl in small:
                    out.append(wl)
                elif core in acronyms:
                    out.append(w.upper())
                elif core and core.isalpha() and len(core) <= 5 and not (set(core) & vowels):
                    # No vowels: an initialism, keep it capitalized.
                    out.append(w.upper())
                elif core.isdigit():
                    out.append(w)
                else:
                    out.append(w[:1].upper() + w[1:].lower())
            return " ".join(out)

        def valid(s: str) -> bool:
            if not s or len(s) < 2:
                return False
            toks = s.split()
            if not (1 <= len(toks) <= 12):
                return False
            if not any(c.isalpha() for c in s):
                return False
            if compact(s) in ("the", "us", "and", "it", "we", "a", "an"):
                return False
            return True

        name_keywords = (
            "fund", "committee", "pac", "party", "congress", "senate", "house",
            "victory", "campaign", "action", "project", "majority", "alliance",
            "for ", "inc", "leadership", "club", "coalition", "council",
            "association", "network", "caucus", "trust", "governor", "president",
        )

        def numbers_ok(s: str) -> bool:
            """Digits in a committee name must be short (district/state numbers) or a year;
            long runs of digits mean an address, PO Box, ZIP or phone number leaked in."""
            for nd in re.findall(r"\d+", s):
                if len(nd) <= 2:
                    continue
                if len(nd) == 4 and (nd.startswith("19") or nd.startswith("20")):
                    continue
                return False
            return True

        def confident(s: str) -> bool:
            """Only accept a deterministic answer we can corroborate from the email text."""
            if not valid(s):
                return False
            low = s.lower()
            if "@" in s or "http" in low or ".com" in low or ".org" in low or ".net" in low:
                return False
            if not numbers_ok(s):
                return False
            occ = compact_text.count(compact(s))
            if is_acronym(s):
                # A bare initialism must be repeated somewhere in the email.
                return occ >= 2
            if any(k in low for k in name_keywords):
                return True
            if len(s.split()) >= 2 and occ >= 2:
                return True
            return False

        candidates = []
        for m in opener_re.finditer(text):
            seg = cut_segment(text[m.end():])
            name = strip_edges(seg)
            if not name:
                continue
            name = char_dedup(name)
            name = " ".join(word_dedup(name.split()))
            name = strip_edges(name)
            name = strip_article(name, text)
            if not valid(name):
                continue
            if is_acronym(name):
                variant = name
            else:
                variant = best_variant(name, text)
                variant = char_dedup(variant)
                if not any(c.islower() for c in variant):
                    variant = title_case(variant)
            variant = strip_article(strip_edges(variant), text)
            if confident(variant):
                candidates.append(variant)

        if candidates:
            # Prefer the most frequently recovered name; ties go to the first found.
            counts = {}
            for c in candidates:
                key = compact(c)
                counts[key] = counts.get(key, 0) + 1
            best = max(candidates, key=lambda c: (counts[compact(c)], -candidates.index(c)))
            return dspy.Prediction(committee=str(best).strip())

        # Deterministic extraction failed or was not trustworthy: fall back to one LM call.
        out = self.fallback(email_body=body)
        name = strip_edges(normalize_ws(str(out.committee or "")))
        name = char_dedup(name)
        name = " ".join(word_dedup(name.split()))
        name = strip_article(strip_edges(name), text)
        return dspy.Prediction(committee=name)

